import { ParameterValue } from "@/components/commandly/types/flat";
import { Command, Tool } from "@/components/commandly/types/flat";
import {
  ParameterRenderContext,
  ParameterRendererEntry,
} from "@/components/commandly/types/renderer";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command as UICommand,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { MultiSelect } from "@/components/ui/multi-select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Switch } from "@/components/ui/switch";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { CheckIcon, ChevronsUpDownIcon, InfoIcon, PlusIcon, XIcon } from "lucide-react";
import React, { useMemo } from "react";

const findDefaultCommand = (tool: Tool): Command | null => {
  const nameMatchCommand = tool.commands.find(
    (command) => command.name.toLowerCase() === tool.binaryName.toLowerCase(),
  );
  if (nameMatchCommand) return nameMatchCommand;

  return tool.commands.length > 0 ? tool.commands[0] : null;
};

interface ParameterLabelProps {
  name: string;
  longFlag?: string;
  shortFlag?: string;
  isRequired?: boolean;
  isGlobal?: boolean;
  description?: string;
  className?: string;
  children?: React.ReactNode;
}

function ParameterLabel({
  name,
  longFlag,
  shortFlag,
  isRequired,
  isGlobal,
  description,
  className,
  children,
}: ParameterLabelProps) {
  return (
    <Label className={className}>
      {name}
      {(longFlag || shortFlag) && (
        <span className="ml-1 text-muted-foreground">
          ({[longFlag, shortFlag].filter(Boolean).join(", ")})
        </span>
      )}
      {isRequired && <span className="ml-1 text-destructive">*</span>}
      {description?.trim() && (
        <Tooltip>
          <TooltipTrigger>
            <InfoIcon className="h-3.5 w-3.5" />
          </TooltipTrigger>
          <TooltipContent>
            <span>{description}</span>
          </TooltipContent>
        </Tooltip>
      )}
      {children}
      {isGlobal && (
        <Badge
          variant="outline"
          className="ml-2 text-xs"
        >
          global
        </Badge>
      )}
    </Label>
  );
}

function FlagInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="flex items-center space-x-2">
      <Switch
        checked={value === "true" || value === true}
        onCheckedChange={onUpdate}
      />
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.name}
        longFlag={parameter.longFlag}
        shortFlag={parameter.shortFlag}
        isRequired={parameter.isRequired}
        isGlobal={parameter.isGlobal}
        description={parameter.description}
      />
    </div>
  );
}

function OptionEnumInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  const [open, setOpen] = React.useState(false);
  const separator = parameter.enum?.separator || ",";
  const options =
    parameter.enum?.values?.map((e) => ({
      value: e.value,
      label: e.displayName || e.value,
    })) ?? [];

  const label = (
    <ParameterLabel
      className="select-auto"
      name={parameter.name}
      longFlag={parameter.longFlag}
      shortFlag={parameter.shortFlag}
      isRequired={parameter.isRequired}
      isGlobal={parameter.isGlobal}
      description={parameter.description}
    />
  );

  if (parameter.enum?.allowMultiple) {
    const selected = Array.isArray(value)
      ? (value as string[]).filter(Boolean)
      : value
        ? (value as string).split(separator).filter(Boolean)
        : [];
    return (
      <div className="space-y-2">
        {label}
        <MultiSelect
          options={options}
          defaultValue={selected}
          onValueChange={(vals) => onUpdate(vals.join(separator))}
          placeholder="Select options"
        />
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {label}
      <Popover
        open={open}
        onOpenChange={setOpen}
      >
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className="w-full justify-between font-normal"
          >
            {options.find((o) => o.value === value)?.label ?? "Select an option"}
            <ChevronsUpDownIcon className="opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className="w-[--radix-popover-trigger-width] p-0"
          align="start"
        >
          <UICommand>
            <CommandInput placeholder="Search..." />
            <CommandList>
              <CommandEmpty>No option found.</CommandEmpty>
              <CommandGroup>
                {options.map((option) => (
                  <CommandItem
                    key={option.value}
                    value={option.value}
                    onSelect={(currentValue) => {
                      onUpdate(currentValue === value ? "" : currentValue);
                      setOpen(false);
                    }}
                  >
                    {option.label}
                    <CheckIcon
                      className={cn(
                        "ml-auto",
                        value === option.value ? "opacity-100" : "opacity-0",
                      )}
                    />
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </UICommand>
        </PopoverContent>
      </Popover>
    </div>
  );
}

function OptionBooleanInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="flex items-center space-x-2">
      <Switch
        checked={value === "true" || value === true}
        onCheckedChange={(checked) => onUpdate(checked.toString())}
      />
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.name}
        longFlag={parameter.longFlag}
        shortFlag={parameter.shortFlag}
        isRequired={parameter.isRequired}
        isGlobal={parameter.isGlobal}
        description={parameter.description}
      />
    </div>
  );
}

function OptionTextInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="space-y-2">
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.name}
        longFlag={parameter.longFlag}
        shortFlag={parameter.shortFlag}
        isRequired={parameter.isRequired}
        isGlobal={parameter.isGlobal}
        description={parameter.description}
      />
      <Input
        type={parameter.dataType === "Number" ? "number" : "text"}
        value={parameter.dataType === "Number" ? (value as number) : (value as string)}
        onChange={(e) => onUpdate(e.target.value)}
        placeholder="Enter value"
      />
    </div>
  );
}

function ArgumentInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="space-y-2">
      <ParameterLabel
        name={parameter.name}
        isRequired={parameter.isRequired}
        description={parameter.description}
      >
        <Badge
          variant="secondary"
          className="ml-2 text-xs"
        >
          {parameter.parameterType}
          {parameter.position !== undefined && ` (${parameter.position})`}
        </Badge>
      </ParameterLabel>
      <Input
        type={parameter.dataType === "Number" ? "number" : "text"}
        value={parameter.dataType === "Number" ? (value as number) : (value as string)}
        onChange={(e) => onUpdate(e.target.value)}
        placeholder="Enter value"
      />
    </div>
  );
}

interface RepeatableWrapperProps {
  parameter: ParameterRenderContext["parameter"];
  value: ParameterRenderContext["value"];
  onUpdate: ParameterRenderContext["onUpdate"];
  renderEntry: ParameterRendererEntry["component"];
}

function RepeatableWrapper({ parameter, value, onUpdate, renderEntry }: RepeatableWrapperProps) {
  const toArray = (v: ParameterRenderContext["value"]): string[] => {
    if (Array.isArray(v)) return v;
    if (v !== undefined && v !== "" && v !== false) return [String(v)];
    return [""];
  };

  const values = toArray(value);

  const updateAt = (index: number, val: ParameterRenderContext["value"]) => {
    const next = [...values];
    next[index] = String(val);
    onUpdate(next);
  };

  const addRow = () => onUpdate([...values, ""]);

  const removeAt = (index: number) => {
    const next = values.filter((_, i) => i !== index);
    onUpdate(next);
  };

  return (
    <div className="space-y-2">
      {values.map((val, index) => (
        <div
          key={index}
          className="flex items-start gap-2"
        >
          <div className="flex-1">
            {renderEntry({ parameter, value: val, onUpdate: (v) => updateAt(index, v) })}
          </div>
          {index > 0 && (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="mt-6 shrink-0"
              onClick={() => removeAt(index)}
            >
              <XIcon className="h-4 w-4" />
            </Button>
          )}
        </div>
      ))}
      <Button
        type="button"
        variant="ghost"
        size="sm"
        className="h-7 px-2 text-muted-foreground"
        onClick={addRow}
      >
        <PlusIcon className="mr-1 h-3.5 w-3.5" />
        Add another
      </Button>
    </div>
  );
}

export function defaultComponents(): ParameterRendererEntry[] {
  return [
    { condition: (p) => p.parameterType === "Flag", component: (ctx) => <FlagInput {...ctx} /> },
    {
      condition: (p) => p.parameterType === "Argument",
      component: (ctx) => <ArgumentInput {...ctx} />,
    },
    {
      condition: (p) => p.parameterType === "Option" && p.dataType === "Enum",
      component: (ctx) => <OptionEnumInput {...ctx} />,
    },
    {
      condition: (p) => p.parameterType === "Option" && p.dataType === "Boolean",
      component: (ctx) => <OptionBooleanInput {...ctx} />,
    },
    {
      condition: (p) => p.parameterType === "Option",
      component: (ctx) => <OptionTextInput {...ctx} />,
    },
  ];
}

interface ToolRendererProps {
  selectedCommand?: Command | null;
  tool: Tool;
  catalog?: ParameterRendererEntry[];
  parameterValues: Record<string, ParameterValue>;
  updateParameterValue: (parameterKey: string, value: ParameterValue) => void;
}

export function ToolRenderer({
  selectedCommand: providedCommand,
  tool,
  catalog = defaultComponents(),
  parameterValues,
  updateParameterValue,
}: ToolRendererProps) {
  const selectedCommand =
    providedCommand === undefined ? findDefaultCommand(tool) : providedCommand;
  const hasCommands = tool.commands.length > 0;

  const visibleParameters = useMemo(() => {
    if (!hasCommands || !selectedCommand) {
      return tool.parameters.filter((p) => !p.commandKey || p.isGlobal);
    }
    return tool.parameters.filter(
      (param) => param.commandKey === selectedCommand?.key || param.isGlobal,
    );
  }, [tool, hasCommands, selectedCommand]);

  return (
    <React.Fragment>
      <div className="space-y-4">
        {visibleParameters.length > 0 ? (
          visibleParameters.map((parameter) => {
            const value = parameterValues[parameter.key] ?? "";
            const onUpdate = (val: ParameterValue) => updateParameterValue(parameter.key, val);
            const entry = catalog.find((e) => e.condition(parameter));
            if (!entry) return null;
            return (
              <React.Fragment key={parameter.key}>
                {parameter.isRepeatable ? (
                  <RepeatableWrapper
                    parameter={parameter}
                    value={value}
                    onUpdate={onUpdate}
                    renderEntry={entry.component}
                  />
                ) : (
                  entry.component({ parameter, value, onUpdate })
                )}
              </React.Fragment>
            );
          })
        ) : (
          <p className="text-sm text-muted-foreground">No parameters available for this command.</p>
        )}
      </div>
    </React.Fragment>
  );
}

import type { Parameter, ParameterValue } from "@/components/commandly/types/flat";
import type { ReactElement } from "react";

export type ParameterRenderContext = {
  parameter: Parameter;
  value: ParameterValue;
  onUpdate: (value: ParameterValue) => void;
};

export type ParameterRendererEntry = {
  condition: (parameter: Parameter) => boolean;
  component: (context: ParameterRenderContext) => ReactElement | null;
};

export interface ToolInfo {
  /** A brief human-readable description of what the tool does. */
  description?: string;
  /** The version string of the tool (e.g. "1.0.0"). */
  version?: string;
  /** The homepage or documentation URL for the tool. */
  url?: string;
}

export interface Command {
  /** Unique identifier for this command within the tool. */
  key: string;
  /** Key of the parent command; used to represent subcommand nesting. */
  parentCommandKey?: string;
  /** Human-readable display name of the command. */
  name: string;
  /** Brief description of what this command does. */
  description?: string;
  /** Whether this command opens an interactive session or prompt. */
  interactive?: boolean;
  /** Display sort position relative to sibling commands. */
  sortOrder?: number;
}

export interface ParameterEnumValue {
  /** The raw value passed to the CLI for this choice. */
  value: string;
  /** Human-readable label shown to the user for this enum choice. */
  displayName: string;
  /** Description of what this enum value does or represents. */
  description?: string;
  /** Whether this is the default selection when no value is provided. */
  isDefault?: boolean;
  /** Display sort position relative to sibling enum values. */
  sortOrder?: number;
}

export interface ParameterEnumValues {
  /** The list of allowed enum choices. */
  values: ParameterEnumValue[];
  /** Whether the user can select multiple values at once. */
  allowMultiple?: boolean;
  /** Separator character used when joining multiple selected values. */
  separator?: string;
}

export type ParameterValidationType =
  | "min_length"
  | "max_length"
  | "min_value"
  | "max_value"
  | "regex";

export interface ParameterValidation {
  /** Unique identifier for this validation rule. */
  key: string;
  /** The type of validation to apply. */
  validationType: ParameterValidationType;
  /** The value to validate against (e.g. the max length number, or a regex pattern). */
  validationValue: string;
  /** The error message to display when validation fails. */
  errorMessage: string;
}

export type ParameterDependencyType = "requires" | "conflicts_with";

export interface ParameterDependency {
  /** Unique identifier for this dependency rule. */
  key: string;
  /** Key of the parameter that owns this dependency. */
  parameterKey: string;
  /** Key of the parameter this dependency references. */
  dependsOnParameterKey: string;
  /** Whether this parameter requires or conflicts with the referenced parameter. */
  dependencyType: ParameterDependencyType;
  /** Optional value that the referenced parameter must have for this dependency to apply. */
  conditionValue?: string;
}

export type ParameterValue = string | number | boolean | string[];

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ToolMetadata {}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ParameterMetadata {
  /** Arbitrary tags for categorising or filtering parameters. */
  tags?: string[];
}

export type ParameterType = "Flag" | "Option" | "Argument";

export type ParameterDataType = "String" | "Number" | "Boolean" | "Enum";

export interface Parameter {
  /** Unique identifier for this parameter within the tool. */
  key: string;
  /** Human-readable display name of the parameter. */
  name: string;
  /** Key of the command this parameter belongs to; omit for global parameters. */
  commandKey?: string;
  /** Brief description of what this parameter does or accepts. */
  description?: string;
  /** Optional grouping label for organising related parameters in the UI. */
  group?: string;
  /** Additional metadata such as tags. */
  metadata?: ParameterMetadata;
  /** Whether this is a boolean flag, a key-value option, or a positional argument. */
  parameterType: ParameterType;
  /** The data type of the parameter's value. */
  dataType: ParameterDataType;
  /** Whether the user must provide this parameter. */
  isRequired?: boolean;
  /** Whether this parameter can be specified multiple times. */
  isRepeatable?: boolean;
  /** Whether this parameter applies to all commands rather than a single command. */
  isGlobal?: boolean;
  /** The single-character short flag (e.g. "-v"). */
  shortFlag?: string;
  /** The long-form flag or option name (e.g. "--verbose"). */
  longFlag?: string;
  /** Zero-based position index for positional arguments. */
  position?: number;
  /** Display sort position relative to sibling parameters. */
  sortOrder?: number;
  /** Separator character used when the option accepts multiple values in one argument (e.g. ","). */
  arraySeparator?: string;
  /** Separator between key and value for key=value style options (e.g. "="). */
  keyValueSeparator?: string;
  /** Allowed enum choices when dataType is "Enum". */
  enum?: ParameterEnumValues;
  /** Validation rules applied to this parameter's value. */
  validations?: ParameterValidation[];
  /** Dependencies on other parameters (requires or conflicts-with relationships). */
  dependencies?: ParameterDependency[];
}

export type ExclusionType = "mutual_exclusive" | "required_one_of";

export interface ExclusionGroup {
  /** Unique identifier for this exclusion group. */
  key?: string;
  /** Key of the command this exclusion group belongs to; omit for global groups. */
  commandKey?: string;
  /** Human-readable name for this exclusion group. */
  name: string;
  /** Whether parameters in this group are mutually exclusive or one is required. */
  exclusionType: ExclusionType;
  /** Keys of the parameters that participate in this exclusion group. */
  parameterKeys: string[];
}

export interface Tool {
  /** Unique binary name for the tool that it can be invoked from the command line (e.g. "httpx"). */
  binaryName: string;
  /** Human-readable display name for the tool (e.g. "HTTPx"). */
  displayName: string;
  /** Whether the root tool invocation opens an interactive session or prompt. */
  interactive?: boolean;
  /** General information about the tool such as description, version, and URL. */
  info?: ToolInfo;
  /** List of all commands and subcommands defined for this tool. */
  commands: Command[];
  /** Flat list of all parameters across all commands and global scope. */
  parameters: Parameter[];
  /** Groups of parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: ExclusionGroup[];
  /** Arbitrary metadata attached to the tool. */
  metadata?: ToolMetadata;
}

import type {
  ExclusionType,
  ParameterDataType,
  ParameterDependencyType,
  ParameterEnumValues,
  ParameterMetadata,
  ParameterType,
  ParameterValidationType,
  ToolInfo,
  ToolMetadata,
} from "@/components/commandly/types/flat";

export interface NestedParameterValidation {
  /** The type of validation to apply. */
  validationType: ParameterValidationType;
  /** The value to validate against (e.g. max length number or regex pattern). */
  validationValue: string;
  /** The error message to display when validation fails. */
  errorMessage: string;
}

export interface NestedParameterDependency {
  /** Name of the parameter this dependency references. */
  dependsOnParameter: string;
  /** Whether this parameter requires or conflicts with the referenced parameter. */
  dependencyType: ParameterDependencyType;
  /** Optional value that the referenced parameter must have for this dependency to apply. */
  conditionValue?: string;
}

export interface NestedParameter {
  /** Human-readable display name of the parameter. */
  name: string;
  /** Brief description of what this parameter does or accepts. */
  description?: string;
  /** Optional grouping label for organising related parameters in the UI. */
  group?: string;
  /** Whether this is a boolean flag, a key-value option, or a positional argument. */
  parameterType: ParameterType;
  /** The data type of the parameter's value. */
  dataType: ParameterDataType;
  /** Additional metadata such as tags. */
  metadata?: ParameterMetadata;
  /** Whether the user must provide this parameter. */
  isRequired?: boolean;
  /** Whether this parameter can be specified multiple times. */
  isRepeatable?: boolean;
  /** Whether this parameter applies to all commands rather than a single command. */
  isGlobal?: boolean;
  /** The single-character short flag (e.g. "-v"). */
  shortFlag?: string;
  /** The long-form flag or option name (e.g. "--verbose"). */
  longFlag?: string;
  /** Zero-based position index for positional arguments. */
  position?: number;
  /** Display sort position relative to sibling parameters. */
  sortOrder?: number;
  /** Separator character used when the option accepts multiple values in one argument (e.g. ","). */
  arraySeparator?: string;
  /** Separator between key and value for key=value style options (e.g. "="). */
  keyValueSeparator?: string;
  /** Allowed enum choices when dataType is "Enum". */
  enum?: ParameterEnumValues;
  /** Validation rules applied to this parameter's value. */
  validations?: NestedParameterValidation[];
  /** Dependencies on other parameters (requires or conflicts-with relationships). */
  dependencies?: NestedParameterDependency[];
}

export interface NestedCommand {
  /** Human-readable display name of the command. */
  name: string;
  /** Brief description of what this command does. */
  description?: string;
  /** Whether this command opens an interactive session or prompt. */
  interactive?: boolean;
  /** Display sort position relative to sibling commands. */
  sortOrder?: number;
  /** Parameters that belong directly to this command. */
  parameters: NestedParameter[];
  /** Nested subcommands of this command. */
  subcommands: NestedCommand[] /** Groups of parameters with mutual exclusion or required-one-of constraints scoped to this command. */;
  exclusionGroups?: NestedExclusionGroup[];
}

export interface NestedExclusionGroup {
  /** Human-readable name for this exclusion group. */
  name: string;
  /** Whether parameters in this group are mutually exclusive or one is required. */
  exclusionType: ExclusionType;
  /** Names of the parameters that participate in this exclusion group. */
  parameters: string[];
}

export interface NestedTool {
  /** Unique binary name for the tool that it can be invoked from the command line (e.g. "httpx"). */
  binaryName: string;
  /** Human-readable display name for the tool (e.g. "HTTPx"). */
  displayName: string;
  /** Whether the root tool invocation opens an interactive session or prompt. */
  interactive?: boolean;
  /** General information about the tool such as description, version, and URL. */
  info?: ToolInfo;
  /** The homepage or documentation URL for the tool. */
  url?: string;
  /** Parameters that belong to the root invocation when no commands exist. */
  rootParameters: NestedParameter[];
  /** Parameters that apply to all commands globally. */
  globalParameters: NestedParameter[];
  /** Hierarchical list of commands and their nested subcommands. */
  commands: NestedCommand[];
  /** Groups of parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: NestedExclusionGroup[] | null;
  /** Arbitrary metadata attached to the tool. */
  metadata?: ToolMetadata;
}
